import { createHash } from 'node:crypto'
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
import { decodeFunctionData, encodeFunctionResult } from 'viem'
import {
  ORIGINAL_GHO,
  UMBRELLA_GHO_ROUTE,
  UMBRELLA_STKGHO,
  VERIFIED_STKGHO_IMPLEMENTATION,
} from '@/lib/carry/umbrellaGhoExit'
import { finishHolderNativeHistoryOriginalSeries } from '@/lib/carry/holderNativeHistoryOriginals.server'
import { UMBRELLA_GHO_NATIVE_ABI } from '@/lib/carry/umbrellaGhoNativeCapacity'
import {
  acquireUmbrellaGhoNativeCapacity,
  selectedOriginalUmbrellaGhoNativeCapacity,
  getLastUmbrellaGhoNativeCapacityDiagnostic,
} from '@/lib/carry/umbrellaGhoNativeCapacity.server'
// Mocked native-controller scaffolding exercises orchestration/private object identity only.
// These tests do not claim genuine configured native acquisition authority.
const state = vi.hoisted(() => ({
  calls: [] as any[],
  mode: '',
  completed: 0,
  finishing: 0,
  retentionEvents: [] as string[],
  retentionMode: '',
}))
vi.mock('@/lib/carry/holderNativeHistoryOriginals.server', () => ({
  beginHolderNativeHistoryOriginalSeries: vi.fn((input: unknown) => {
    state.retentionEvents.push('begin')
    expect(input).toEqual({ kind: 'umbrella_gho_current', sharesRaw: null })
    return Object.freeze({ schema: 'holder_native_history_original_series_handle_v1' })
  }),
  recordHolderNativeHistoryOriginalBatch: vi.fn((_handle: unknown, input: any) => {
    state.retentionEvents.push('record')
    expect(input.receipt.ledger).toBeDefined()
    return Object.freeze({ status: 'partial', reason: 'pending_replay' })
  }),
  finishHolderNativeHistoryOriginalSeries: vi.fn((_handle: unknown, input: any) => {
    state.retentionEvents.push(input.qualification ? 'finish-qualified' : 'finish-rejected')
    if (state.retentionMode === 'expires-after-sink') vi.setSystemTime(NOW + 1800000)
    return Object.freeze({
      status: state.retentionMode.startsWith('unavailable')
        ? 'unavailable'
        : input.qualification
          ? 'retained'
          : 'partial',
      reason:
        state.retentionMode === 'unavailable-artifact_changed'
          ? 'artifact_changed'
          : state.retentionMode === 'source_changed' ||
              state.retentionMode === 'unavailable-source_changed'
            ? 'source_changed'
            : state.retentionMode === 'unavailable'
              ? 'filesystem_unavailable'
              : input.reason,
      kind: 'umbrella_gho_current',
      producerReplayQualification: input.qualification,
      recordedBatches: 1,
      originalAuthority: false,
      authenticated: false,
      executionQualified: false,
      historicalOwnership: false,
    })
  }),
}))
vi.mock('@/scripts/research/usd3-hypothetical-history-capture.mjs', () => ({
  configuredUsd3HypotheticalOrigins: vi.fn(async () => {
    state.retentionEvents.push('origins')
    return [
      { host: 'eth-mainnet.g.alchemy.com', url: 'https://eth-mainnet.g.alchemy.com/test' },
      { host: 'rpc.ankr.com', url: 'https://rpc.ankr.com/test' },
    ]
  }),
  parseUsd3HypotheticalJson: (text: string) => JSON.parse(text),
  createUsd3HypotheticalCaptureControl: vi.fn(() => controller()),
}))
const proxyCode =
  ''
const implementationCode =
  ''
// GHO code: actual74 native original IDs57/70 (8046 bytes), independently approved keccak dd5142…0172.
const ghoCode =
  ''
const NOW = Date.parse('2026-10-08T18:00:00.000Z')
const owner = '0x1234567890123456789012345678901234567890'
const source = {
  chainId: 1 as const,
  blockNumber: 26149326,
  blockHash: '0x' + 'a'.repeat(64),
  blockTime: new Date(NOW - 60000).toISOString(),
  finalized: true as const,
}
const binding = {
  routeKey: UMBRELLA_GHO_ROUTE,
  destination: UMBRELLA_STKGHO,
  owner,
  asset: ORIGINAL_GHO,
  assetDecimals: 18 as const,
  shareDecimals: 18 as const,
  source,
  asOfMs: NOW,
}
const sha = (value: string | Buffer) => createHash('sha256').update(value).digest('hex')
function nativeResult(request: any, host: string): unknown {
  const p = request.params
  const second = host === 'rpc.ankr.com'
  if (request.method === 'eth_getBlockByNumber')
    return {
      number:
        '0x' +
        (
          source.blockNumber + (p[0] === 'finalized' ? (state.mode === 'unfinalized' ? -1 : 3) : 0)
        ).toString(16),
      hash: state.mode === 'header' && second ? '0x' + 'b'.repeat(64) : source.blockHash,
      timestamp: '0x' + (Date.parse(source.blockTime) / 1000).toString(16),
      transactions: Array(93).fill('0x00'),
    }
  if (request.method === 'eth_chainId') return '0x1'
  if (request.method === 'eth_getCode')
    return state.mode === 'code' && second
      ? '0x00'
      : p[0] === UMBRELLA_STKGHO
        ? proxyCode
        : p[0] === ORIGINAL_GHO
          ? ghoCode
          : implementationCode
  if (request.method === 'eth_getStorageAt')
    return '0x' + '0'.repeat(24) + VERIFIED_STKGHO_IMPLEMENTATION.slice(2)
  const call = decodeFunctionData({ abi: UMBRELLA_GHO_NATIVE_ABI, data: p[0].data })
  const values: Record<string, unknown> = {
    asset: state.mode === 'asset' ? owner : ORIGINAL_GHO,
    decimals: 18,
    paused: false,
    balanceOf: p[0].to === ORIGINAL_GHO ? 800n : state.mode === 'shares' && second ? 101n : 100n,
    totalAssets: 1000n,
    totalSupply: 500n,
    getCooldown: 1728000n,
    getUnstakeWindow: 172800n,
    getStakerCooldown: [40n, Date.parse(source.blockTime) / 1000, 20],
    maxRedeem: 40n,
    getMaxSlashableAssets: 0n,
    previewRedeem: call.functionName === 'previewRedeem' ? (call.args![0] as bigint) * 2n : 0n,
  }
  return encodeFunctionResult({
    abi: UMBRELLA_GHO_NATIVE_ABI,
    functionName: call.functionName,
    result: values[call.functionName],
  } as never)
}
function controller() {
  const ledger: any[] = []
  let finished: any
  return {
    beginStage: () => undefined,
    fetcher: async (url: string, options: any) => {
      const request = JSON.parse(options.body),
        host = new URL(url).hostname
      state.calls.push({ host, request, redirect: options.redirect })
      if (state.mode === 'failure') throw Error('mock_provider_failure')
      const physicalId = ledger.length + 1
      const result = nativeResult(request, host)
      let body = JSON.stringify({ jsonrpc: '2.0', id: request.id, result })
      if (
        (state.mode === 'echo-plain' ||
          state.mode === 'echo-escaped' ||
          state.mode === 'echo-escaped-key') &&
        request.method === 'eth_getBlockByNumber'
      ) {
        body = JSON.stringify({
          jsonrpc: '2.0',
          id: request.id,
          result:
            state.mode === 'echo-escaped-key'
              ? { ...(result as object), test: 'ordinary native metadata' }
              : { ...(result as object), extra: url },
        })
        if (state.mode === 'echo-escaped' || state.mode === 'echo-escaped-key')
          body = body.replaceAll('test', '\\u0074\\u0065\\u0073\\u0074')
      }
      if (state.mode === 'malformed-escaped') body = '{"result":"\\u0074\\u0065\\u0073\\u0074"'
      if (state.mode === 'malformed-unescaped') body = '{"result":"incomplete"'
      const bytes = Buffer.from(body)
      const row = {
        physicalId,
        host,
        request,
        startedAtUtc: new Date(Date.now()).toISOString(),
        completedAtUtc: new Date(Date.now()).toISOString(),
        accepted: true,
        status: 'success',
        bodyBytes: bytes.length,
        rawBodyBase64: bytes.toString('base64'),
        bodySha256: sha(bytes),
      }
      ledger.push(row)
      // Like the real default controller, keep exact raw bytes before rejecting JSON.
      if (state.mode === 'malformed-escaped' || state.mode === 'malformed-unescaped') {
        row.accepted = false
        row.status = 'failed'
        throw Error('mock_controller_json_rejected')
      }
      state.completed++
      if (state.mode === 'expires' && state.completed === 46) vi.setSystemTime(NOW + 1800000)
      return new Response(bytes, { headers: { 'x-usd3-physical-id': String(physicalId) } })
    },
    finish: async () => {
      state.finishing++
      return (finished ??= {
        physicalStarts: ledger.length,
        pendingSettlements: 0,
        failure: null,
        ledger,
        terminalCommitments: ledger.map((row) => ({
          physicalId: row.physicalId,
          rowSha256: sha(JSON.stringify(row)),
        })),
      })
    },
  }
}
beforeEach(() => {
  vi.useFakeTimers()
  vi.setSystemTime(NOW)
  state.calls = []
  state.mode = ''
  state.completed = 0
  state.finishing = 0
  state.retentionEvents = []
  state.retentionMode = ''
})
afterEach(() => vi.useRealTimers())
describe('protected Umbrella native current reader (mock controller, no native authority claim)', () => {
  it('measures full and partial cooldown S before independent previews, retaining original identity only', async () => {
    const acquisition = await acquireUmbrellaGhoNativeCapacity(binding)
    expect(
      acquisition,
      JSON.stringify({
        phase: getLastUmbrellaGhoNativeCapacityDiagnostic()?.phase,
        callsLength: state.calls.length,
        finishing: state.finishing,
        lastRPCmethod: state.calls.at(-1)?.request.method,
        lastNativeFn:
          state.calls.at(-1)?.request.method === 'eth_call'
            ? decodeFunctionData({
                abi: UMBRELLA_GHO_NATIVE_ABI,
                data: state.calls.at(-1)!.request.params[0].data,
              }).functionName
            : null,
      }),
    ).not.toBeNull()
    expect(state.calls).toHaveLength(46)
    expect(state.calls.every((call) => call.redirect === 'error')).toBe(true)
    expect(acquisition!.fact.fullSharesRaw).toBe('100')
    expect(acquisition!.fact.fullEaRaw).toBe('200')
    expect(acquisition!.fact.cooldownSharesRaw).toBe('40')
    expect(acquisition!.fact.cooldownSnapshotEaRaw).toBe('80')
    expect(acquisition!.fact.MRaw).toBeNull()
    expect(selectedOriginalUmbrellaGhoNativeCapacity(acquisition, binding)).toBe(acquisition!.fact)
    expect(
      selectedOriginalUmbrellaGhoNativeCapacity(structuredClone(acquisition), binding),
    ).toBeNull()
    expect(selectedOriginalUmbrellaGhoNativeCapacity(acquisition!.fact, binding)).toBeNull()
    for (const host of ['eth-mainnet.g.alchemy.com', 'rpc.ankr.com']) {
      const calls = state.calls
        .filter((c) => c.host === host && c.request.method === 'eth_call')
        .map((c) =>
          decodeFunctionData({ abi: UMBRELLA_GHO_NATIVE_ABI, data: c.request.params[0].data }),
        )
      const previews = calls.filter((c) => c.functionName === 'previewRedeem')
      expect(previews.map((c) => c.args![0])).toEqual([100n, 40n])
      expect(calls.findIndex((c) => c.functionName === 'balanceOf')).toBeLessThan(
        calls.findIndex((c) => c.functionName === 'previewRedeem'),
      )
    }
    expect(state.retentionEvents).toEqual(['begin', 'origins', 'record', 'finish-qualified'])
    expect(acquisition!.retention.originalAuthority).toBe(false)
    expect(acquisition!.availableAtUtc).toBe(new Date(NOW).toISOString())
    expect(acquisition!.originalAuthority).toBe(false)
    expect(Object.isFrozen(acquisition!.fact)).toBe(true)
  })
  it.each(['routeKey', 'destination', 'owner', 'asset', 'assetDecimals', 'shareDecimals'])(
    'rejects invalid %s before any capture',
    async (key) => {
      const changed = { ...binding, [key]: key.endsWith('Decimals') ? 6 : 'wrong' }
      expect(await acquireUmbrellaGhoNativeCapacity(changed as never)).toBeNull()
      expect(state.calls).toHaveLength(0)
    },
  )
  it('never invokes a caller accessor', async () => {
    const getter = vi.fn(() => owner)
    const input = { ...binding }
    Object.defineProperty(input, 'owner', { enumerable: true, get: getter })
    expect(await acquireUmbrellaGhoNativeCapacity(input)).toBeNull()
    expect(getter).not.toHaveBeenCalled()
    expect(state.calls).toHaveLength(0)
  })
  it.each(['unfinalized', 'header', 'code', 'asset', 'shares', 'failure', 'expires'])(
    'rejects %s without an invented entitlement, and cleans up for a later attempt',
    async (mode) => {
      state.mode = mode
      expect(await acquireUmbrellaGhoNativeCapacity(binding)).toBeNull()
      expect(state.retentionEvents).toEqual(['begin', 'origins', 'record', 'finish-rejected'])
      state.mode = ''
      state.calls = []
      state.completed = 0
      vi.setSystemTime(NOW)
      expect(await acquireUmbrellaGhoNativeCapacity(binding)).not.toBeNull()
    },
  )
  it('rejects stale/future sources before RPC and an expired or drifting original selection', async () => {
    expect(
      await acquireUmbrellaGhoNativeCapacity({
        ...binding,
        source: { ...source, blockTime: new Date(NOW - 1800001).toISOString() },
      }),
    ).toBeNull()
    expect(
      await acquireUmbrellaGhoNativeCapacity({
        ...binding,
        source: { ...source, blockTime: new Date(NOW + 1000).toISOString() },
      }),
    ).toBeNull()
    expect(state.calls).toHaveLength(0)
    const original = await acquireUmbrellaGhoNativeCapacity(binding)
    expect(original).not.toBeNull()
    expect(
      selectedOriginalUmbrellaGhoNativeCapacity(original, { ...binding, owner: ORIGINAL_GHO }),
    ).toBeNull()
    expect(
      selectedOriginalUmbrellaGhoNativeCapacity(original, {
        ...binding,
        source: { ...source, blockHash: '0x' + 'b'.repeat(64) },
      }),
    ).toBeNull()
    vi.setSystemTime(NOW + 1800000)
    expect(
      selectedOriginalUmbrellaGhoNativeCapacity(original, { ...binding, asOfMs: NOW + 1800000 }),
    ).toBeNull()
  })
  it.each(['echo-plain', 'echo-escaped', 'echo-escaped-key'])(
    'rejects %s before persisting any raw receipt',
    async (mode) => {
      state.mode = mode
      expect(await acquireUmbrellaGhoNativeCapacity(binding)).toBeNull()
      expect(state.retentionEvents).not.toContain('record')
      expect(state.retentionEvents.at(-1)).toBe('finish-rejected')
      expect(getLastUmbrellaGhoNativeCapacityDiagnostic()?.phase).toBe('raw_receipt')
    },
  )
  it('rejects malformed escaped raw bytes retained by a failed controller before any receipt write', async () => {
    state.mode = 'malformed-escaped'
    vi.mocked(finishHolderNativeHistoryOriginalSeries).mockClear()
    expect(await acquireUmbrellaGhoNativeCapacity(binding)).toBeNull()
    expect(state.finishing).toBe(1)
    expect(state.retentionEvents).not.toContain('record')
    expect(vi.mocked(finishHolderNativeHistoryOriginalSeries).mock.calls.at(-1)?.[1].reason).toBe(
      'invalid_input',
    )
  })
  it('retains ordinary malformed unescaped failure bytes without claiming native qualification', async () => {
    state.mode = 'malformed-unescaped'
    expect(await acquireUmbrellaGhoNativeCapacity(binding)).toBeNull()
    expect(state.retentionEvents).toEqual(['begin', 'origins', 'record', 'finish-rejected'])
  })
  it('rechecks freshness after sink completion and rejects a changed source witness', async () => {
    state.retentionMode = 'expires-after-sink'
    expect(await acquireUmbrellaGhoNativeCapacity(binding)).toBeNull()
    expect(state.retentionEvents.at(-1)).toBe('finish-qualified')
    vi.setSystemTime(NOW)
    state.retentionMode = 'source_changed'
    expect(await acquireUmbrellaGhoNativeCapacity(binding)).toBeNull()
  })
  it.each(['unavailable-source_changed', 'unavailable-artifact_changed'])(
    'rejects detected %s despite an earlier sink failure',
    async (mode) => {
      state.retentionMode = mode
      const original = await acquireUmbrellaGhoNativeCapacity(binding)
      expect(original).toBeNull()
      expect(getLastUmbrellaGhoNativeCapacityDiagnostic()?.phase).toBe('retention')
      expect(selectedOriginalUmbrellaGhoNativeCapacity(original, binding)).toBeNull()
    },
  )
  it('reports unavailable retention separately without minting archive authority', async () => {
    state.retentionMode = 'unavailable'
    const acquisition = await acquireUmbrellaGhoNativeCapacity(binding)
    expect(acquisition, JSON.stringify(getLastUmbrellaGhoNativeCapacityDiagnostic())).not.toBeNull()
    expect(acquisition!.retention.reason).toBe('filesystem_unavailable')
    expect(acquisition!.originalAuthority).toBe(false)
    expect(
      selectedOriginalUmbrellaGhoNativeCapacity(structuredClone(acquisition), binding),
    ).toBeNull()
  })
  it('binds a pre-await snapshot despite later caller mutation', async () => {
    const mutable = { ...binding, source: { ...source } }
    const pending = acquireUmbrellaGhoNativeCapacity(mutable)
    mutable.owner = ORIGINAL_GHO
    mutable.source.blockHash = '0x' + 'b'.repeat(64)
    const original = await pending
    expect(original).not.toBeNull()
    expect(original!.fact.owner).toBe(owner)
    expect(original!.fact.source.blockHash).toBe(source.blockHash)
    expect(selectedOriginalUmbrellaGhoNativeCapacity(original, binding)).toBe(original!.fact)
    expect(selectedOriginalUmbrellaGhoNativeCapacity(original, mutable)).toBeNull()
  })
  it('bounds concurrent acquisition instead of queuing another native batch', async () => {
    const first = acquireUmbrellaGhoNativeCapacity(binding)
    expect(await acquireUmbrellaGhoNativeCapacity(binding)).toBeNull()
    expect(await first).not.toBeNull()
    expect(state.calls).toHaveLength(46)
  })
})
